// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount, bool ownerReverts) public {
        amount = bound(amount, 0, 1 ether);

        OwnerHelper helper = new OwnerHelper(ownerReverts);

        vm.deal(address(this), amount);

        address payer = address(0xBEEF);
        vm.deal(payer, amount);
        vm.prank(payer);
        (bool s, ) = address(c).call{value: amount}("");
        require(s, "funding failed");

        helper.callSetReceiverBehavior(ownerReverts);

        bool ok;
        try c.withdraw{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == amount);
        }
    }

    bool private _ownerShouldRevert;

    function setOwnerShouldRevert(bool v) external {
        _ownerShouldRevert = v;
    }

    receive() external payable {
        if (_ownerShouldRevert) revert("owner revert");
    }
}

contract OwnerHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }
    function callSetReceiverBehavior(bool v) external {
        (bool s, ) = msg.sender.call(abi.encodeWithSelector(InvMutTest.setOwnerShouldRevert.selector, v));
        require(s, "callback failed");
    }
}
